function PVPArenaPlayerQuizInfoNode:Awake()
    self.listenerConf = {
        [Constants.EventNames.PVPArenaRequestHomeSuccess]    = Bind(self, self.OnRequestHomeSuccessAction),
        [Constants.EventNames.PVPArenaRequestQuizSuccess]    = Bind(self, self.OnRequestQuizSuccessAction),
        [Constants.EventNames.PVPArenaRequestSeasonRankSuccess]    = Bind(self, self.OnRequestSeasonRankSuccessAction),
