    end

    UIEventProxy.Create(self.LookPlayerInfoArea.gameObject).onPointerClick = Bind(self, self.OnClickLookPlayerInfoAction)
    UIEventProxy.Create(self.BtnSelect.gameObject).onPointerClick = Bind(self, self.OnClickQuizBtnAction)
end

