function PVPArenaPlayerQuizInfoNode:RefreshUI(info, playerId)
    self.info = info
    self.playerId = playerId

    local excludeDialogs = {
        {id = Constants.UITypeIds.PVPArenaPlayerQuizDialog}
    }
    PVPArenaUtils.RefreshPlayerHeadNode(self.PlayerHeadNode.gameObject, playerId, info, excludeDialogs)

    self.TxtLV.text = info.level
    self.TextName.text = info.name

    self:RefreshBottomUI()

end

function PVPArenaPlayerQuizInfoNode:RefreshBottomUI()
    local seasonFlag = pvpArenaComponent:GetSeasonFlag()
    local isQuiz = seasonFlag == Constants.PVPArenaSeasonFullStatus.Quiz
    local quizzedMap = pvpArenaComponent:GetQuizzedMap()
    --- 是否投过票
    local isQuizzed = quizzedMap[tostring(self.playerId)] ~= nil
    local isShowBtn = isQuiz and not isQuizzed
    KTool.SetActive(self.BtnSelect.gameObject, isShowBtn)
    if not isShowBtn then
        KTool.SetActive(self.TicketGroup.gameObject, not isQuiz)
        KTool.SetActive(self.NOTicketGroup.gameObject, isQuiz)
        if not isQuiz then
            local matcherInfo = checkTable(self.pvpArenaDojo.matcherInfo)
            local info = checkTable(matcherInfo[tostring(self.playerId)])
            self.TxtTicketNumber.text = tostring(info.quizzedNum)
        end
    end
end

function PVPArenaPlayerQuizInfoNode:OnRequestHomeSuccessAction()
    self:RefreshBottomUI()
end

function PVPArenaPlayerQuizInfoNode:OnRequestSeasonRankSuccessAction(seasonId, seasonRank)
    if self.seasonId ~= seasonId then return end
    self.TitleNumText.text = PVPArenaUtils.GetRankTextBySeasonRank(seasonRank, self.playerId)
end

function PVPArenaPlayerQuizInfoNode:OnRequestQuizSuccessAction()
    self:RefreshBottomUI()
end

