function PVPArenaPlayerQuizInfoNode:OnClickLookPlayerInfoAction()
    local excludeDialogs = {}
    PVPArenaUtils.ShowMatcherInfoDialog(self.playerId, excludeDialogs)
end

function PVPArenaPlayerQuizInfoNode:OnClickQuizBtnAction()
    if not self:CheckQuizState() then return end

    local mainPanelStatus  = pvpArenaComponent:GetMainPanelStatus()
    if mainPanelStatus == Constants.PVPArenaMainPanelStatus.QuizComplete then
        local quizPrice      = pvpArenaComponent:GetParamsRowNum(Constants.PVPArenaParamsIds.QuizPrice)
        local buyQuizGoodsId = pvpArenaComponent:GetParamsRowNum(Constants.PVPArenaParamsIds.BuyQuizGoodsId)
        ---@type GoodsConfMgr
        local goodsConfMgr = GoodsConfMgr:GetInstance()
        ---@type GoodsVo
        local goodsVo      = goodsConfMgr:GetGoodsVoById(buyQuizGoodsId)
        if GoodsUtils.GetThingNo(buyQuizGoodsId) < quizPrice then
            GameUtils.Toast(localize("_name_不足", {_name_ = goodsVo.name}))
            return
        end

        GameUtils.SecondConfirm(localize("是否使用_num__goodsName_推选<color=#e71f55>_playerName_</color>获胜?", {
            _num_ = quizPrice, _goodsName_ = goodsVo.name, _playerName_ = self.info.name}), function()
            if not self:CheckQuizState() then return end
            pvpArenaComponent:RequestQuiz(self.playerId)
        end, nil, localize("[剩余竞猜次数x_times_]", {_times_ = self.pvpArenaDojo.quizTicketNum}))

        return
    end

    GameUtils.SecondConfirm(localize("是否推选<color=#e71f55>_playerName_</color>获胜?", {_playerName_ = self.info.name}), function()
        if not self:CheckQuizState() then return end
        pvpArenaComponent:RequestQuiz(self.playerId)
    end, nil, localize("[剩余竞猜次数x_times_]", {_times_ = self.pvpArenaDojo.quizTicketNum}))

end

function PVPArenaPlayerQuizInfoNode:CheckQuizState()
    local seasonFlag        = pvpArenaComponent:GetSeasonFlag()
    local isQuiz            = seasonFlag == Constants.PVPArenaSeasonFullStatus.Quiz
    if not isQuiz then
        GameUtils.Toast(localize("竞猜期已结束, 不可推选"))
        return isQuiz
    end
    return isQuiz
end

